import React, { useState } from 'react';
import { Box, Button, Chip, IconButton, Menu, MenuItem, Paper, Typography } from '@mui/material';
import { ModBadge, testKey } from './Moderation';
import { canModerate, roleInSpace, type SpaceModeration } from '../utils/moderation';

// The on-demand moderation surfaces (Slim Round S3, 2026-11-20):
// the per-message action menu and the participants panel. These
// render only inside an opened chat space's moderation surfaces,
// so they ship in their own chunk (loaded via ModerationLazy) —
// the always-rendered moderation pieces (badges, pinned area,
// locked banner, system lines, the useSpaceModeration hook) stay
// in Moderation.tsx with the message flow. Moved verbatim from
// Moderation.tsx; behaviour and testids unchanged.

export interface MessageModMenuProps {
  messageKey: string;
  pinned: boolean;
  onPin: () => void;
  onUnpin: () => void;
  onRemove: () => void;
}

// The per-message action menu (owner + moderators only — callers
// render it only for them). Pin/unpin and Remove live here.
export const MessageModMenu: React.FC<MessageModMenuProps> = ({
  messageKey,
  pinned,
  onPin,
  onUnpin,
  onRemove,
}) => {
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const san = testKey(messageKey);
  const close = () => setAnchor(null);
  return (
    <>
      <IconButton
        size="small"
        aria-label="Moderation actions for this message"
        data-testid={`mod-menu-${san}`}
        onClick={e => setAnchor(e.currentTarget)}
        sx={{ p: 0.25, fontSize: '0.9rem', lineHeight: 1 }}
      >
        ⋯
      </IconButton>
      <Menu anchorEl={anchor} open={anchor !== null} onClose={close}>
        {pinned ? (
          <MenuItem
            data-testid={`mod-act-unpin-${san}`}
            onClick={() => {
              close();
              onUnpin();
            }}
          >
            📌 Unpin message
          </MenuItem>
        ) : (
          <MenuItem
            data-testid={`mod-act-pin-${san}`}
            onClick={() => {
              close();
              onPin();
            }}
          >
            📌 Pin message
          </MenuItem>
        )}
        <MenuItem
          data-testid={`mod-act-remove-${san}`}
          onClick={() => {
            close();
            onRemove();
          }}
        >
          🛡️ Remove message
        </MenuItem>
      </Menu>
    </>
  );
};

export interface ParticipantRowData {
  key: string;
  label: string;
}

export interface ParticipantsPanelProps {
  mod: SpaceModeration;
  ownerKey: string;
  viewerKey: string;
  participants: ParticipantRowData[];
  onAppoint: (key: string, label: string) => void;
  onUnappoint: (key: string, label: string) => void;
  onMute: (key: string, label: string) => void;
  onUnmute: (key: string, label: string) => void;
  onRemove: (key: string, label: string) => void;
}

// The people-in-this-space panel: the member list, the badges,
// and — for the owner and moderators — the appoint / mute /
// remove controls on each person's row. Removed participants are
// NOT passed in: they have left the space and its lists.
// Permission shape (Round 35 brief): the OWNER appoints and
// removes moderators and can act on anyone but themselves;
// MODERATORS can mute/remove plain members; nobody acts on the
// owner or on themselves.
export const ParticipantsPanel: React.FC<ParticipantsPanelProps> = ({
  mod,
  ownerKey,
  viewerKey,
  participants,
  onAppoint,
  onUnappoint,
  onMute,
  onUnmute,
  onRemove,
}) => {
  const viewerRole = roleInSpace(mod, ownerKey, viewerKey);
  return (
    <Paper sx={{ p: 2, mb: 2, borderRadius: 3 }} data-testid="mod-participants">
      <Typography variant="subtitle1" gutterBottom>
        People in this space
      </Typography>
      {participants.map(p => {
        const role = roleInSpace(mod, ownerKey, p.key);
        const muted = mod.mutedKeys.includes(p.key);
        const isSelf = p.key === viewerKey;
        const showControls = canModerate(viewerRole) && !isSelf && role !== 'owner';
        const canAppoint = viewerRole === 'owner' && showControls;
        const canActOn = showControls && (viewerRole === 'owner' || role === 'member');
        return (
          <Box
            key={p.key}
            data-testid={`mod-participant-${testKey(p.key)}`}
            sx={{
              display: 'flex',
              gap: 1,
              flexWrap: 'wrap',
              alignItems: 'center',
              py: 0.75,
              borderBottom: '1px solid rgba(255,255,255,0.06)',
            }}
          >
            <Typography variant="body2" sx={{ fontWeight: 600 }}>
              {p.label}
              {isSelf ? ' (you)' : ''}
            </Typography>
            <ModBadge role={role} />
            {muted && <Chip size="small" variant="outlined" label="Muted" sx={{ height: 18 }} />}
            {canAppoint &&
              (role === 'moderator' ? (
                <Button
                  size="small"
                  data-testid={`mod-unappoint-${testKey(p.key)}`}
                  onClick={() => onUnappoint(p.key, p.label)}
                >
                  Remove moderator
                </Button>
              ) : (
                <Button
                  size="small"
                  data-testid={`mod-appoint-${testKey(p.key)}`}
                  onClick={() => onAppoint(p.key, p.label)}
                >
                  Make moderator
                </Button>
              ))}
            {canActOn &&
              (muted ? (
                <Button
                  size="small"
                  data-testid={`mod-unmute-${testKey(p.key)}`}
                  onClick={() => onUnmute(p.key, p.label)}
                >
                  Unmute
                </Button>
              ) : (
                <Button
                  size="small"
                  data-testid={`mod-mute-${testKey(p.key)}`}
                  onClick={() => onMute(p.key, p.label)}
                >
                  Mute
                </Button>
              ))}
            {canActOn && (
              <Button
                size="small"
                color="error"
                data-testid={`mod-remove-participant-${testKey(p.key)}`}
                onClick={() => onRemove(p.key, p.label)}
              >
                Remove from space
              </Button>
            )}
          </Box>
        );
      })}
      <Typography variant="caption" color="text.secondary">
        Moderation here is built in: the owner can appoint moderators, and owners and moderators can
        pin, remove posts, mute or remove people, and lock the space — every action posts a small
        note in this space only. Demo moderation, on this device.
      </Typography>
    </Paper>
  );
};
